"""Generate fixed-schema projection readers from the registered Go descriptor.
Run go run ./cmd/schema > fields.json, then python3 generate.py.
Only selected singular strings are supported; these are benchmark specializations.
"""
import json
from pathlib import Path
fields=json.loads(Path('fields.json').read_text())
go_cases='\n'.join(f'case {f["number"]}: idx={i}' for i,f in enumerate(fields))
c_cases='\n'.join(f'case {f["number"]}: idx={i}; break;' for i,f in enumerate(fields))
rust_cases='\n'.join(f'{f["number"]} => {i},' for i,f in enumerate(fields))
go='''//go:build all || gencode

// Code generated by generate.py from fields.json. DO NOT EDIT.
package lab
import("fmt";"google.golang.org/protobuf/encoding/protowire";"google.golang.org/protobuf/reflect/protoreflect")
func generatedScan(raw []byte,mask uint32,first bool)([4]string,error){var out [4]string;var seen uint32
 for d:=raw;len(d)>0;{num,typ,n:=protowire.ConsumeTag(d);if n<0{return out,protowire.ParseError(n)};d=d[n:];idx:=-1
 switch num {GO_CASES}
 if idx>=0&&typ==protowire.BytesType&&(mask&(1<<idx))!=0&&(!first||seen&(1<<idx)==0) {x,n:=protowire.ConsumeBytes(d);if n<0{return out,protowire.ParseError(n)};out[idx]=StringView(x);seen|=1<<idx;d=d[n:];if first&&seen==mask{break}} else {n:=protowire.ConsumeFieldValue(num,typ,d);if n<0{return out,protowire.ParseError(n)};d=d[n:]}}
 return out,nil}
func init(){for _,first:=range []bool{false,true}{name:="go_codegen_last";if first{name="go_codegen_first"};Register(Backend{Name:name,FirstWins:first,ValidUTF8Assumed:true,Prepare:func(fields []protoreflect.FieldDescriptor)(func([]byte)(Session,error),error){if len(fields)!=1&&len(fields)!=4{return nil,fmt.Errorf("unsupported query")};mask:=uint32(1<<len(fields))-1;return func(raw []byte)(Session,error){values,e:=generatedScan(raw,mask,first);return &planSession{raw,values,fields},e},nil},Note:"generated numeric switch, one scan for selected fields, alias strings"})}}
'''.replace('GO_CASES',go_cases)
Path('generated.go').write_text(go)
header='''#include <stddef.h>
#include <stdint.h>
typedef struct { size_t offset; size_t length; } lab_span;
int lab_scan(const unsigned char*,size_t,uint32_t,int,lab_span*);
int lab_project(const unsigned char*,size_t,uint32_t,int,lab_span*);
int lab_batch(const unsigned char*,const size_t*,size_t,uint32_t,int,lab_span*);
int lab_noop(void);
'''
c='''// Code generated by generate.py. Scalar projection only; no group support.
#include "bridge.h"
static int varint(const unsigned char*d,size_t n,size_t*p,uint64_t*out){uint64_t v=0;for(unsigned j=0;j<10;j++){if(*p>=n)return -1;unsigned char b=d[(*p)++];if(j==9&&b>1)return -1;v|=(uint64_t)(b&127)<<(j*7);if(b<128){*out=v;return 0;}}return -1;}
static int record(const unsigned char*d,size_t n,size_t*p,uint64_t*tag,size_t*start,size_t*len){uint64_t v=0;if(varint(d,n,p,tag)||(*tag>>3)==0||(*tag>>3)>536870911)return -1;*start=*p;switch(*tag&7){case 0:if(varint(d,n,p,&v))return -1;break;case 1:if(n-*p<8)return -1;*p+=8;break;case 2:if(varint(d,n,p,&v)||v>n-*p)return -1;*start=*p;*p+=(size_t)v;break;case 5:if(n-*p<4)return -1;*p+=4;break;default:return -1;}*len=*p-*start;return 0;}
int lab_noop(void){return 0;}
int lab_scan(const unsigned char*d,size_t n,uint32_t field,int first,lab_span*out){size_t p=0;out[0]=(lab_span){0,0};while(p<n){uint64_t tag;size_t start,len;if(record(d,n,&p,&tag,&start,&len))return -1;if((tag>>3)==field&&(tag&7)==2){out[0]=(lab_span){start,len};if(first)return 0;}}return 0;}
int lab_project(const unsigned char*d,size_t n,uint32_t mask,int first,lab_span*out){size_t p=0;uint32_t seen=0;for(int i=0;i<4;i++)out[i]=(lab_span){0,0};while(p<n){uint64_t tag;size_t start,len;if(record(d,n,&p,&tag,&start,&len))return -1;int idx=-1;switch(tag>>3){C_CASES}if(idx>=0&&(tag&7)==2&&(mask&(1u<<idx))&&(!first||!(seen&(1u<<idx)))){out[idx]=(lab_span){start,len};seen|=1u<<idx;if(first&&seen==mask)return 0;}}return 0;}
int lab_batch(const unsigned char*d,const size_t*offsets,size_t count,uint32_t mask,int first,lab_span*out){for(size_t i=0;i<count;i++){if(lab_project(d+offsets[i],offsets[i+1]-offsets[i],mask,first,out+i*4))return -1;}return 0;}
'''.replace('C_CASES',c_cases)
Path('internal/cbridge').mkdir(parents=True,exist_ok=True)
Path('internal/cbridge/bridge.h').write_text(header)
Path('internal/cbridge/bridge.c').write_text(c)
rust='''// Code generated by generate.py. Scalar projection only; no group support.
#![no_std]
use core::slice;
#[repr(C)] #[derive(Clone,Copy)] pub struct Span{offset:usize,length:usize}
#[panic_handler] fn panic(_: &core::panic::PanicInfo)->!{unsafe extern "C" {fn abort()->!;}unsafe{abort()}}
fn varint(d:&[u8],p:&mut usize)->Result<u64,()>{let mut v=0;for j in 0..10 {if *p>=d.len(){return Err(());}let b=d[*p];*p+=1;if j==9&&b>1{return Err(());}v|=((b&127) as u64)<<(7*j);if b<128{return Ok(v);}}Err(())}
fn record(d:&[u8],p:&mut usize)->Result<(u64,Span),()>{let tag=varint(d,p)?;if tag>>3==0||tag>>3>536870911{return Err(());}let mut start=*p;match tag&7{0=>{varint(d,p)?;},1=>{if d.len()-*p<8{return Err(());}*p+=8;},2=>{let n=varint(d,p)?;if n>(d.len()-*p) as u64{return Err(());}start=*p;*p+=n as usize;},5=>{if d.len()-*p<4{return Err(());}*p+=4;},_=>return Err(())};Ok((tag,Span{offset:start,length:*p-start}))}
#[unsafe(no_mangle)] pub extern "C" fn rust_noop()->i32{0}
#[unsafe(no_mangle)] pub unsafe extern "C" fn rust_scan(data:*const u8,n:usize,field:u32,first:i32,out:*mut Span)->i32 {let d=unsafe{slice::from_raw_parts(data,n)};unsafe{*out=Span{offset:0,length:0};}let mut p=0;while p<n{let Ok((tag,span))=record(d,&mut p)else{return -1;};if tag>>3==field as u64&&tag&7==2{unsafe{*out=span;}if first!=0{return 0;}}}0}
fn project(d:&[u8],mask:u32,first:bool,out:&mut [Span])->i32{out.fill(Span{offset:0,length:0});let mut p=0;let mut seen=0;while p<d.len(){let Ok((tag,span))=record(d,&mut p)else{return -1;};let idx=match tag>>3 {RUST_CASES _=>4};if idx<4&&tag&7==2&&mask&(1<<idx)!=0&&(!first||seen&(1<<idx)==0) {out[idx]=span;seen|=1<<idx;if first&&seen==mask{return 0;}}}0}
#[unsafe(no_mangle)] pub unsafe extern "C" fn rust_project(data:*const u8,n:usize,mask:u32,first:i32,out:*mut Span)->i32{project(unsafe{slice::from_raw_parts(data,n)},mask,first!=0,unsafe{slice::from_raw_parts_mut(out,4)})}
#[unsafe(no_mangle)] pub unsafe extern "C" fn rust_batch(data:*const u8,offsets:*const usize,count:usize,mask:u32,first:i32,out:*mut Span)->i32{let o=unsafe{slice::from_raw_parts(offsets,count+1)};for i in 0..count{if o[i+1]<o[i]{return -1;}let result=project(unsafe{slice::from_raw_parts(data.add(o[i]),o[i+1]-o[i])},mask,first!=0,unsafe{slice::from_raw_parts_mut(out.add(i*4),4)});if result!=0{return result;}}0}
'''.replace('RUST_CASES',rust_cases)
Path('internal/rbridge').mkdir(parents=True,exist_ok=True)
Path('internal/rbridge/reader.rs').write_text(rust)
for kind,prefix in [('c','lab'),('r','rust')]:
    d=Path(f'internal/{kind}bridge')
    if kind=='r':d.joinpath('bridge.h').write_text(header.replace('lab_','rust_'))
    flags='#cgo CFLAGS: -O3\n'
    if kind=='r': flags+='#cgo LDFLAGS: ${SRCDIR}/libreader.a -ldl -lm\n'
    bridge='''package PACKAGE
/*
FLAGS#include "bridge.h"
*/
import "C"
import("fmt";"runtime";"unsafe")
func Noop(){C.PREFIX_noop()}
func Single(raw []byte,field uint32,first bool)(int,int,error){if len(raw)==0{return 0,0,nil};var out C.PREFIX_span;mode:=C.int(0);if first{mode=1};if C.PREFIX_scan((*C.uchar)(unsafe.Pointer(unsafe.SliceData(raw))),C.size_t(len(raw)),C.uint32_t(field),mode,&out)!=0{return 0,0,fmt.Errorf("invalid wire")};runtime.KeepAlive(raw);return int(out.offset),int(out.length),nil}
func Project(raw []byte,mask uint32,first bool)([4][2]int,error){if len(raw)==0{return [4][2]int{},nil};var out [4]C.PREFIX_span;mode:=C.int(0);if first{mode=1};if C.PREFIX_project((*C.uchar)(unsafe.Pointer(unsafe.SliceData(raw))),C.size_t(len(raw)),C.uint32_t(mask),mode,&out[0])!=0{return [4][2]int{},fmt.Errorf("invalid wire")};runtime.KeepAlive(raw);var res [4][2]int;for i,v:=range out{res[i]=[2]int{int(v.offset),int(v.length)}};return res,nil}
func Batch(raw []byte,offsets []uintptr,mask uint32,first bool,out []uintptr)error{mode:=C.int(0);if first{mode=1};if len(raw)==0{for _,v:=range offsets{if v!=0{return fmt.Errorf("invalid empty batch")}};clear(out);return nil};if len(offsets)<2||len(out)<(len(offsets)-1)*8{return fmt.Errorf("invalid batch")};if C.PREFIX_batch((*C.uchar)(unsafe.Pointer(unsafe.SliceData(raw))),(*C.size_t)(unsafe.Pointer(unsafe.SliceData(offsets))),C.size_t(len(offsets)-1),C.uint32_t(mask),mode,(*C.PREFIX_span)(unsafe.Pointer(unsafe.SliceData(out))))!=0{return fmt.Errorf("invalid wire")};runtime.KeepAlive(raw);runtime.KeepAlive(offsets);runtime.KeepAlive(out);return nil}
'''.replace('PACKAGE',f'{kind}bridge').replace('FLAGS',flags).replace('PREFIX',prefix)
    # span typedef has backend-specific name in Rust header.
    d.joinpath('bridge.go').write_text(bridge)
    backend='''//go:build all || TAG
package lab
import("example.com/cel-wire-lab/internal/PACKAGE";"google.golang.org/protobuf/reflect/protoreflect")
type PACKAGEsession struct{raw []byte;first bool}
func(s *PACKAGEsession)Close(){}
func(s *PACKAGEsession)Get(fd protoreflect.FieldDescriptor)(string,error){start,n,e:=PACKAGE.Single(s.raw,uint32(fd.Number()),s.first);if e!=nil{return "",e};return StringView(s.raw[start:start+n]),nil}
func init(){for _,first:=range []bool{false,true}{suffix:="last";if first{suffix="first"};Register(Backend{Name:"LABEL_generic_"+suffix,FirstWins:first,ValidUTF8Assumed:true,Prepare:func(_ []protoreflect.FieldDescriptor)(func([]byte)(Session,error),error){return func(raw []byte)(Session,error){return &PACKAGEsession{raw,first},nil},nil},Note:"one cgo call per field; no UTF8 validation"})
Register(Backend{Name:"LABEL_codegen_"+suffix,FirstWins:first,ValidUTF8Assumed:true,Prepare:func(fields []protoreflect.FieldDescriptor)(func([]byte)(Session,error),error){mask:=uint32(1<<len(fields))-1;return func(raw []byte)(Session,error){spans,e:=PACKAGE.Project(raw,mask,first);if e!=nil{return nil,e};s:=&planSession{raw:raw,fields:fields};for i,p:=range spans{s.values[i]=StringView(raw[p[0]:p[0]+p[1]])};return s,nil},nil},Note:"generated projection; one cgo call per event; no UTF8 validation"})}}
'''.replace('TAG','cffi' if kind=='c' else 'rustffi').replace('PACKAGE',f'{kind}bridge').replace('LABEL','c' if kind=='c' else 'rust')
    Path(f'backend_{kind}ffi.go').write_text(backend)
print('Generated Go/C/Rust readers from', fields)
